const base = '/work/workspace/deliverable/';
const s1 = JSON.parse(fs.readFileSync(base+'session1/march_mor.json','utf8'));
const s2 = JSON.parse(fs.readFileSync(base+'session2/april_mor.json','utf8'));
const s3 = JSON.parse(fs.readFileSync(base+'session3/cod_schedule.json','utf8'));
results.push('OK 3 JSON files parse');

// S1 roll-forward
const r1 = s1.part1_total_operating_receipts ?? s1.total_operating_receipts;
// inspect structure
function findNums(o, path='', out={}){ if(typeof o==='number'){out[path]=o;} else if(o&&typeof o==='object'){for(const k in o) findNums(o[k], path?path+'.'+k:k, out);} return out; }
const f1 = findNums(s1), f2 = findNums(s2), f3 = findNums(s3);
results.push('S1 nums: '+JSON.stringify(Object.entries(f1).filter(([k,v])=>v>1000).slice(0,20)));
results.push('S2 nums: '+JSON.stringify(Object.entries(f2).filter(([k,v])=>v>1000).slice(0,20)));
results.push('S3 nums: '+JSON.stringify(Object.entries(f3).filter(([k,v])=>v>1000)));

// S3 arithmetic
chk('GUC x35%', 8400000*0.35, 2940000);
chk('discharge', 8400000-2940000, s3.debt_discharged);
chk('nol_after', 6100000-5460000, s3.attribute_reduction.nol_after);
chk('2,940,000/0.35 tie', 2940000/0.35, 8400000);
chk('level installment', 2940000/24, 122500);
chk('obligation post-1st', 2940000-122500, 2817500);
chk('current split', 12*122500, 1470000);
chk('noncurrent split', 11*122500, 1347500);
chk('splits sum', 1470000+1347500, 2817500);
chk('election NOL path', 6100000-2260000, 3840000);
chk('election reduction', 3200000+2260000, 5460000);
chk('remaining default', 640000+3200000, 3840000);
chk('nonGUC', 16200000-8400000, 7800000);
chk('insolvency shortfall', 16200000-14000000, 2200000);

results.join('\n');

